/* --------------------
      Ticket Form
-------------------- */
#ticketModal .modal-content {
  max-width: 900px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: #e0f1fc; /* light blue card */
  border-radius: 12px;
  padding: 22px;
}

#ticketSearch {
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid #92b1db;
  margin-bottom: 12px;
  width: 100%;
  background: #d2e3f4;
  color: #0f1c2b;
  outline: none;
}

#ticketSearch:focus {
  border-color: #2c5da0;
  box-shadow: 0 0 0 2px rgba(44,93,160,0.2);
}

#ticketsLeftPanel {
  background: #d2e3f4;
  padding: 12px;
  border-radius: 10px;
  max-height: 300px;
  overflow-y: auto;
}

#ticketDetailContainer {
  margin-top: 12px;
  background: #d2e3f4;
  padding: 16px;
  border-radius: 12px;
}

#ticketDetailContainer button {
  background: #2c5da0;
  color: #fff;
  padding: 8px 14px;
  border-radius: 8px;
  border: none;
  cursor: pointer;
}

#ticketDetailContainer button:hover {
  background: #17375d;
}

/* --------------------
      Add Property Form
-------------------- */
#addPropertyModal form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

#addPropertyModal input,
#addPropertyModal select {
  width: 100%;
  padding: 12px 14px;
  border-radius: 8px;
  border: 1px solid #92b1db;
  background: #d2e3f4;
  font-size: 14px;
  color: #0f1c2b;
  outline: none;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

#addPropertyModal input:focus,
#addPropertyModal select:focus {
  border-color: #2c5da0;
  box-shadow: 0 0 0 2px rgba(44,93,160,0.2);
}

#addPropertyModal input[type="file"] {
  background: #e0f1fc;
  padding: 10px;
  border: 1px solid #92b1db;
  cursor: pointer;
}

#addPropertyModal button[type="submit"] {
  background: #2c5da0;
  color: #fff;
  border-radius: 8px;
  padding: 10px 16px;
  border: none;
  cursor: pointer;
  font-weight: 600;
  transition: background 0.2s ease, transform 0.2s ease;
}

#addPropertyModal button[type="submit"]:hover {
  background: #17375d;
  transform: translateY(-1px);
}
/* --------------------
      Property Details Modal
-------------------- */

#propertyDetailsModal .modal-content {
  background: #cde0f3; /* same as other modals */
  border-radius: 14px;
  width: 100%;
  max-width: 620px;
  padding: 24px;
  box-shadow: 0 20px 50px rgba(0,0,0,0.25);
  position: relative;
  animation: fadePop 0.25s ease-out;
}

@keyframes fadePop {
  from {
    opacity: 0;
    transform: translateY(-10px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

#propertyDetailsModal .close {
  position: absolute;
  top: 12px;
  right: 12px;
  font-size: 22px;
  font-weight: bold;
  color: #17375d;
  background: none;
  border: none;
  cursor: pointer;
}

#propertyDetailsModal h2 {
  text-align: center;
  color: #17375d;
  margin-bottom: 16px;
  font-size: 1.6rem;
}

#propertyDetailsModal img {
  width: 100%;
  max-height: 280px;
  object-fit: cover;
  border-radius: 10px;
  margin-bottom: 16px;
  box-shadow: 0 6px 18px rgba(0,0,0,0.08);
}

#propertyDetailsModal .detail-row {
  margin-bottom: 10px;
  font-size: 1rem;
  color: #2c4b70;
}

#propertyDetailsModal .detail-row strong {
  color: #17375d;
}

#propertyDetailsModal .details-footer {
  display: flex;
  justify-content: flex-end;
  margin-top: 20px;
}

#propertyDetailsModal .close-btn {
  background: #2c5da0;
  color: #fff;
  padding: 10px 16px;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  font-weight: 600;
  transition: background 0.2s ease, transform 0.2s ease;
}

#propertyDetailsModal .close-btn:hover {
  background: #17375d;
  transform: translateY(-2px);
}
/* Add Property Modal scroll if content is too tall */
#addPropertyModal .modal-content {
  max-height: 90vh;   /* max height relative to viewport */
  overflow-y: auto;   /* vertical scroll if needed */
}
/* Allow the whole modal to scroll if too tall */
#propertyDetailsModal {
  overflow-y: auto;
}

/* Keep the inner content from exceeding the screen height */
#propertyDetailsModal .modal-content {
  max-height: 90vh;
  overflow-y: auto;
}
#adminSidebar {
  max-height: 100vh;
  overflow-y: auto;

  /* Firefox */
  scrollbar-width: thin;
  scrollbar-color: #3498db #f0f0f0; /* thumb | track */
}

/* WebKit (Chrome, Edge, Safari) */
#adminSidebar::-webkit-scrollbar {
  width: 8px;
}

#adminSidebar::-webkit-scrollbar-track {
  background: #f0f0f0;  /* track color */
  border-radius: 4px;
}

#adminSidebar::-webkit-scrollbar-thumb {
  background-color: #3498db; /* scrollbar color */
  border-radius: 4px;
}

#adminSidebar::-webkit-scrollbar-thumb:hover {
  background-color: #21618c; /* darker on hover */
}
/* Make body take full height */
html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  font-family: Arial, sans-serif;
}

/* Parallax background */
body {
  background-image: url('data:image/jpeg;base64,'); /* replace with your image */
  background-attachment: fixed; /* parallax effect */
  background-size: cover;       /* cover the screen */
  background-position: center;  /* center the image */
  background-repeat: no-repeat;
  transition: background-position 0.3s ease-out; /* smooth transition */
}
/* Apply slight transparency to all page content except the background */
header, main, footer, section, div, {
  background-color: #2c5da000; /* remove any solid background */
  opacity: .97; /* slightly transparent (1 = fully opaque) */
}

#ticketModal select#ticketStatus {
  padding: 4px 8px;             /* small padding */
  border: 1px solid #88c0f7;
  border-radius: 5px;
  background-color: #f0f8ff;
  color: #333;
  font-size: 14px;
  width: auto;                  /* shrink to content */
  display: inline-block;        /* keep it inline */
  min-width: 100px;             /* optional: ensure it’s not too tiny */
  appearance: none;
  cursor: pointer;
}

#ticketModal select#ticketStatus:hover,
#ticketModal select#ticketStatus:focus {
  border-color: #5a9be0;
  outline: none;
  background-color: #e6f2fc;
}
/* For main page property images */
.property img {
  width: 100%;
  height: 300px; /* or any fixed height for grid cards */
  object-fit: cover; /* this makes the image fill the container without stretching */
  border-radius: 12px; /* optional, like in modal */
}

/* Optional hover zoom effect */
.property img:hover {
  transform: scale(1.05);
  transition: transform 0.3s ease;
}
.property-id-box {
  background-color: #2b6cb0;
  color: white;
  padding: 2px 6px;
  border-radius: 4px;
  font-weight: bold;
  display: inline-block;
  margin-bottom: 4px;
}


